-- Ревизия каталога приложения 2026.11.2: оборудование в названии и недостающие упражнения; сверяется ExerciseCatalogContractTest.
-- Переименование — новое название у того же id (на id ссылаются тренировки и синхронизация); короткие названия не меняются.
-- Прежнее название остаётся синонимом для голосового ввода. Новая ревизия каталога — новый changeset; этот не редактировать.

UPDATE sizylift.exercise SET name = 'Болгарские выпады с гантелями' WHERE id = '14000000-0000-4000-8000-000000000011' AND user_id IS NULL; -- было «Болгарские выпады»
UPDATE sizylift.exercise SET name = 'Румынская тяга со штангой' WHERE id = '14000000-0000-4000-8000-000000000012' AND user_id IS NULL; -- было «Румынская тяга»
UPDATE sizylift.exercise SET name = 'Подъём на носки стоя в тренажёре' WHERE id = '14000000-0000-4000-8000-000000000049' AND user_id IS NULL; -- было «Подъём на носки стоя»
UPDATE sizylift.exercise SET name = 'Сгибание рук на скамье Скотта со штангой' WHERE id = '14000000-0000-4000-8000-000000000060' AND user_id IS NULL; -- было «Сгибание рук на скамье Скотта»
UPDATE sizylift.exercise SET name = 'Французский жим лёжа со штангой' WHERE id = '14000000-0000-4000-8000-000000000062' AND user_id IS NULL; -- было «Французский жим лёжа»
UPDATE sizylift.exercise SET name = 'Жим штанги лёжа узким хватом' WHERE id = '14000000-0000-4000-8000-000000000063' AND user_id IS NULL; -- было «Жим лёжа узким хватом»




-- Синонимы голосового ввода (docs/voice.md): прежние названия, новые варианты; голое «хаммер» подходило и тяге, и жиму в рычажном тренажёре — снято, остались «тяга в хаммере» и «жим в хаммере».
DELETE FROM sizylift.voice_exercise_alias WHERE exercise_id = '14000000-0000-4000-8000-000000000033' AND alias = 'хаммер';


